CREATE SCHEMA IF NOT EXISTS _setup; CREATE OR REPLACE FUNCTION _setup.exec(script text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ BEGIN EXECUTE script; END; $fn$; REVOKE ALL ON FUNCTION _setup.exec(text) FROM PUBLIC; REVOKE ALL ON SCHEMA _setup FROM PUBLIC, anon, authenticated; GRANT USAGE ON SCHEMA _setup TO sandbox_exec; GRANT EXECUTE ON FUNCTION _setup.exec(text) TO sandbox_exec;